input,select,textarea{width:100%;padding:12px 14px;border:1px solid var(--line2);border-radius:14px;font:inherit;font-size:15.5px;background:#fff;color:var(--ink);transition:border-color .15s,box-shadow .15s}
input[type=file]{padding:10px 12px;background:var(--bg)}
input[type=checkbox]{accent-color:var(--teal2)}
textarea{min-height:110px;resize:vertical}
input:focus,select:focus,textarea:focus{outline:0;border-color:var(--teal3);box-shadow:0 0 0 4px rgba(47,122,110,.16)}
.btn:focus-visible,a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid rgba(47,122,110,.4);outline-offset:2px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:var(--teal);color:#fff;border:1px solid transparent;border-radius:999px;padding:0 24px;min-height:50px;font:600 15.5px var(--font);cursor:pointer;text-decoration:none;margin-top:18px;text-align:center;transition:background .15s,transform .08s}
.btn:hover{background:#0a2925}.btn:active{transform:scale(.98)}
.btn.go{background:var(--ok)}.btn.go:hover{background:#12623e}
.btn.line{background:#fff;color:var(--ink);border-color:var(--line2)}.btn.line:hover{background:var(--fill)}
.btn.stop{background:#fff;color:var(--bad);border-color:#efc3be}.btn.stop:hover{background:var(--badbg)}
.pill{display:inline-flex;align-items:center;gap:6px;padding:3px 11px 3px 9px;border-radius:999px;font-size:12.5px;font-weight:600;line-height:1.45;white-space:nowrap;vertical-align:1px}
.pill::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
.pill.ok{background:var(--okbg);color:var(--ok)}.pill.warn{background:var(--warnbg);color:var(--warn)}.pill.bad{background:var(--badbg);color:var(--bad)}
.pill.info{background:var(--infobg);color:var(--info)}.pill.grey{background:var(--fill);color:var(--muted)}
.callout{border-radius:16px;padding:14px 18px;margin:16px 0;font-size:15px;line-height:1.5}
.callout.ok{background:var(--okbg);color:#0f5132}.callout.warn{background:var(--warnbg);color:#5c3a00}
.callout.bad{background:var(--badbg);color:#7a1a12}.callout.info{background:var(--infobg);color:#173f5f}
table.kv{width:100%;border-collapse:collapse;margin:10px 0}
table.kv td{padding:11px 4px;border-bottom:1px solid var(--line);vertical-align:top;font-size:15px}
table.kv tr:last-child td{border-bottom:0}
table.kv td:first-child{color:var(--muted);width:36%}
table.list{width:100%;border-collapse:collapse;margin:10px 0}
table.list th{font-size:12.5px;color:var(--muted);text-align:left;font-weight:600;padding:8px 8px;border-bottom:1px solid var(--line)}
table.list td{padding:11px 8px;border-bottom:1px solid var(--line);vertical-align:top;font-size:14.5px}
.num{text-align:right;font-variant-numeric:tabular-nums}
.chk{display:grid;grid-template-columns:30px 1fr;gap:10px;padding:12px 0;border-bottom:1px solid var(--line);font-size:15px}
.chk:last-child{border-bottom:0}
.chk .i{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;font-size:13px;font-weight:700}
.chk.ok .i{background:var(--okbg);color:var(--ok)}.chk.warn .i{background:var(--warnbg);color:var(--warn)}.chk.high .i{background:var(--bad);color:#fff}
.chk b{display:block;font-size:15px;font-weight:600}.chk span{color:var(--ink2);font-size:14.5px}
.qcard{display:block;border:1px solid var(--line);border-radius:18px;padding:16px 18px;margin:12px 0;text-decoration:none;color:inherit;background:#fff;transition:border-color .15s,box-shadow .15s}
.qcard:hover{border-color:var(--line2);box-shadow:var(--shadow)}.qcard .t{display:flex;justify-content:space-between;gap:10px;font-weight:650}.qcard .r{margin-top:6px;font-size:14px;color:var(--ink2)}
.stack>form{border-top:1px solid var(--line);padding-top:10px;margin-top:20px}
.stack h3{font-weight:650;font-size:17px;letter-spacing:-.01em;margin:14px 0 2px}
details summary{cursor:pointer}
.sheet h1{font-size:30px}
.sheet table.list td,.sheet table.list th{padding:9px 8px}
.foot{text-align:center;color:var(--muted);font-size:12.5px;margin:12px 16px 40px}
@media(max-width:560px){.card{margin:0;border-radius:0;border-left:0;border-right:0;padding:26px 18px;box-shadow:none}.btn{display:flex;width:100%}.btn.inline{display:inline-flex;width:auto}h1{font-size:27px}}
@media print{.top,.foot,.noprint{display:none!important}body{background:#fff}.card{border:0;margin:0;max-width:none;padding:0;box-shadow:none}}
`;

// A clean, mobile-friendly page for approvers, suppliers, contractors and the certifier.
const page = (title, body, opts = {}) => {
  const cfg = configFrom();
  return `<!doctype html><html lang="en-NZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title>${FONT_LINK}<style>${THEME}</style></head><body>
<header class="top"><b>${BRAND_MARK}${esc(cfg.business_name || 'Tussock Ridge Farming Ltd')}</b><span>${esc(opts.tag || 'Secure link')}</span></header>
<main class="card${opts.wide ? ' wide' : ''}">${body}</main>
<div class="foot">Demo by Forrof. All people, businesses and numbers are fictional.</div></body></html>`;
};

// The rules the agent applies to every supplier invoice. Injected into the nodes that check or show invoices.
// The agent only checks and flags. Approving and paying are always a person's decision.
const norm = (s) => String(s ?? '').trim().toLowerCase();
const digitsOf = (s) => String(s ?? '').replace(/\D/g, '');

// The next payment date on or after `today`: the payDay-th of this month, or of next month once it has passed.
const nextPayDate = (today, payDay) => {
  const d = dateOf(today);
  const month = d.getUTCDate() > payDay ? d.getUTCMonth() + 1 : d.getUTCMonth();
  return isoDay(new Date(Date.UTC(d.getUTCFullYear(), month, payDay)));
};
// Standard rural terms: the 20th of the month following the invoice date.
const dueDateFor = (invoiceDate, payDay) => {
  const d = dateOf(invoiceDate);
  return isoDay(new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, payDay)));
};
const parseChecks = (inv) => { try { return JSON.parse(inv.reasons || '[]'); } catch { return []; } };
const failedChecks = (inv) => parseChecks(inv).filter((c) => !c.ok);

const approverFor = (role, cfg) => (role === 'owner'
  ? { role, title: 'owner', name: cfg.owner_name, email: cfg.owner_email, phone: cfg.owner_phone, token: cfg.approver_token_owner }
  : { role, title: 'operations manager', name: cfg.manager_name, email: cfg.manager_email, phone: cfg.manager_phone, token: cfg.approver_token_manager });

// status → [tone, label]
const INVOICE_STATUS = {
  received: ['grey', 'New, not checked yet'],
  matched: ['info', 'Clean, waiting for approval'],
  flagged: ['warn', 'Flagged, waiting for a decision'],
  approved: ['ok', 'Approved'],
  queried: ['warn', 'Queried with supplier'],
  rejected: ['bad', 'Rejected'],
  scheduled: ['ok', 'In payment file'],
  paid: ['grey', 'Paid'],
};
const invoiceStatusPill = (inv) => { const [tone, label] = INVOICE_STATUS[inv.status] || ['grey', inv.status]; return pill(tone, label); };

// Runs every check on one invoice. ctx = { cfg, suppliers (by id), contracts, dockets, invoices (all), used (contract_id → qty used) }.
// Each check has `text` (for the farm) and, when it fails, `ask` (a sentence that is safe to send to the supplier).
const checkInvoice = (inv, ctx) => {
  const cfg = ctx.cfg;
  const gst = Number(cfg.gst_rate || 0.15);
  const sup = ctx.suppliers[inv.supplier_id];
  const supName = sup ? sup.name : 'this supplier';
  const qty = Number(inv.qty);
  const price = Number(inv.unit_price);
  const total = Number(inv.total);
  const checks = [];
  const add = (id, label, ok, text, extra = {}) => checks.push({ id, label, ok, text, short: ok ? '' : (extra.short || label), ask: ok ? '' : (extra.ask || ''), level: ok ? 'ok' : (extra.level || 'warn'), risk: ok ? 0 : round2(extra.risk || 0) });
  // Only an earlier invoice can make this one a duplicate.
  const earlier = (o) => o.received_at < inv.received_at || (o.received_at === inv.received_at && o.invoice_id < inv.invoice_id);

  // 1. Is there a contract in force for this item?
  const sameItem = ctx.contracts.filter((c) => c.supplier_id === inv.supplier_id && norm(c.item) === norm(inv.item));
  const contract = sameItem.find((c) => inv.invoice_date >= c.valid_from && inv.invoice_date <= c.valid_to);
  if (contract) add('contract', 'Matches a contract', true, `${contract.contract_id}: ${contract.description}.`);
  else if (sameItem.length) add('contract', 'Matches a contract', false, `The ${inv.item} contract with ${supName} was not in force on ${fmtDate(inv.invoice_date)} (it runs ${fmtDate(sameItem[0].valid_from)} to ${fmtDate(sameItem[0].valid_to)}).`,
    { short: 'Contract not in force on the invoice date', ask: `We could not match this invoice to an agreement in force on ${fmtDate(inv.invoice_date)}. Could you send us the agreement it is based on?` });
  else add('contract', 'Matches a contract', false, `No contract or agreed price covers ${inv.item} from ${supName}. Find the agreement, or confirm this is a one-off purchase.`,
    { short: 'No contract covers this item', ask: `We could not match "${inv.item}" to an agreed price on our side. Could you send us the quote or agreement it is based on?` });

  if (contract) {
    // 2. Unit price against the contract, with a small tolerance.
    const agreed = Number(contract.agreed_price);
    const tol = Number(contract.tolerance_pct ?? cfg.price_tolerance_pct ?? 2);
    const diffPct = ((price - agreed) / agreed) * 100;
    if (norm(inv.unit) !== norm(contract.unit)) {
      add('price', 'Price matches the contract', false, `Invoiced per ${inv.unit}, but the contract price is per ${contract.unit}.`,
        { short: 'Priced per a different unit from the contract', ask: `The invoice is priced per ${inv.unit}, but our agreement is per ${contract.unit}. Please check and confirm the price.` });
    } else if (diffPct > tol) {
      const over = round2((price - agreed) * qty);
      add('price', 'Price matches the contract', false, `Unit price ${priceText(price)} is ${diffPct.toFixed(1)}% above the contract price of ${priceText(agreed)} per ${contract.unit}: ${money(over)} too much on ${qtyText(qty)} ${inv.unit} (ex GST).`,
        { short: `Price ${diffPct.toFixed(1)}% over the contract`, risk: over * (1 + gst), ask: `The unit price of ${priceText(price)} per ${contract.unit} is above the agreed ${priceText(agreed)} per ${contract.unit} (${money(over)} more, ex GST). Please check it, or send us the agreement that supports the higher price.` });
    } else if (diffPct > 0.0001) {
      add('price', 'Price matches the contract', true, `${priceText(price)} per ${contract.unit} is ${diffPct.toFixed(1)}% above the contract price, within the ${tol}% tolerance.`);
    } else {
      add('price', 'Price matches the contract', true, `${priceText(price)} per ${contract.unit}${diffPct < -0.0001 ? ' (below' : ' (matches'} the contract price of ${priceText(agreed)}).`);
    }

    // 3. How much of the contract volume is used up?
    const used = ctx.used[contract.contract_id] || 0;
    const agreedQty = Number(contract.qty_agreed);
    if (qty > agreedQty - used + 0.0001) {
      const overQty = round2(used + qty - agreedQty);
      add('volume', 'Within the contract volume', false, `This invoice takes ${contract.item} to ${qtyText(used + qty)} of ${qtyText(agreedQty)} ${contract.unit} agreed (${qtyText(overQty)} ${contract.unit} over). Confirm the price for the extra volume.`,
        { short: `${qtyText(overQty)} ${contract.unit} over the contract volume`, risk: overQty * price * (1 + gst), ask: `This invoice takes our total to ${qtyText(used + qty)} ${contract.unit}, which is above the ${qtyText(agreedQty)} ${contract.unit} we agreed. Please confirm the price that applies to the extra ${qtyText(overQty)} ${contract.unit}.` });
    } else {
      add('volume', 'Within the contract volume', true, `${qtyText(used + qty)} of ${qtyText(agreedQty)} ${contract.unit} used after this invoice.`);
    }
  }

  // 4. Delivery docket: was the delivery signed for, does the quantity match, and was the docket already invoiced?
  const needsDocket = contract ? contract.needs_docket === 'yes' : !!inv.docket_ref;
  if (inv.docket_ref) {
    const docket = ctx.dockets.find((d) => norm(d.docket_ref) === norm(inv.docket_ref) && d.supplier_id === inv.supplier_id);
    const reused = ctx.invoices.find((o) => o.invoice_id !== inv.invoice_id && norm(o.docket_ref) === norm(inv.docket_ref) && o.status !== 'rejected' && earlier(o));
    if (!docket) {
      add('docket', 'Matches a delivery docket', false, `Docket ${inv.docket_ref} is not in the delivery records. Was this delivery signed for?`,
        { short: 'Docket not in the delivery records', ask: `We cannot find delivery docket ${inv.docket_ref} in our records. Could you send us a copy of the signed docket?` });
    } else if (qty > Number(docket.qty) + 0.0001) {
      const short = round2(qty - Number(docket.qty));
      add('docket', 'Matches a delivery docket', false, `Invoiced ${qtyText(qty)} ${inv.unit}, but docket ${docket.docket_ref} shows ${qtyText(docket.qty)} ${docket.unit} delivered on ${fmtDate(docket.delivered_on)}: ${qtyText(short)} ${inv.unit} not delivered (${money(short * price)} ex GST).`,
        { short: `Docket shows ${qtyText(docket.qty)} ${docket.unit}, invoiced ${qtyText(qty)}`, risk: short * price * (1 + gst), ask: `You invoiced ${qtyText(qty)} ${inv.unit}, but our signed docket ${docket.docket_ref} shows ${qtyText(docket.qty)} ${docket.unit} delivered on ${fmtDate(docket.delivered_on)}. Please check and send a corrected invoice.` });
    } else if (reused) {
      add('docket', 'Matches a delivery docket', false, `Docket ${docket.docket_ref} was already invoiced on ${reused.invoice_id} (${reused.supplier_ref}, ${money(reused.total)}). One delivery should be invoiced once.`,
        { short: 'Docket already invoiced', risk: total, ask: `Delivery docket ${docket.docket_ref} has already been invoiced on ${reused.supplier_ref}. Please confirm this invoice is not a repeat.` });
    } else {
      add('docket', 'Matches a delivery docket', true, `Docket ${docket.docket_ref}: ${qtyText(docket.qty)} ${docket.unit} delivered ${fmtDate(docket.delivered_on)}, signed by ${docket.received_by}.`);
    }
  } else if (needsDocket) {
    add('docket', 'Matches a delivery docket', false, 'No delivery docket reference on this invoice. Check the delivery was received before paying.',
      { short: 'No delivery docket number', ask: 'There is no delivery docket number on this invoice. Please send the docket number or a copy of the signed docket.' });
  } else {
    add('docket', 'Matches a delivery docket', true, 'A service invoice: no delivery docket needed.');
  }

  // 5. Arithmetic and GST.
  const net = round2(qty * price);
  const gstExpected = round2(net * gst);
  const problems = [];
  let gstRisk = 0;
  if (Math.abs(Number(inv.net) - net) > 0.02) { problems.push(`Net ${money(inv.net)} is not ${qtyText(qty)} × ${priceText(price)} = ${money(net)}.`); gstRisk = Math.max(gstRisk, Math.abs(Number(inv.net) - net)); }
  if (Math.abs(Number(inv.gst) - gstExpected) > 0.02) { problems.push(`GST is ${money(inv.gst)}, but ${Math.round(gst * 100)}% of ${money(net)} is ${money(gstExpected)}.`); gstRisk = Math.max(gstRisk, Math.abs(Number(inv.gst) - gstExpected)); }
  if (Math.abs(total - (Number(inv.net) + Number(inv.gst))) > 0.02) { problems.push(`The total ${money(total)} is not net plus GST (${money(Number(inv.net) + Number(inv.gst))}).`); gstRisk = Math.max(gstRisk, Math.abs(total - (Number(inv.net) + Number(inv.gst)))); }
  if (problems.length) add('gst', 'Arithmetic and GST add up', false, problems.join(' '), { short: 'GST or total does not add up', risk: gstRisk, ask: `The amounts on this invoice do not add up: ${problems.join(' ')} Please send a corrected invoice.` });
  else add('gst', 'Arithmetic and GST add up', true, `${money(net)} plus GST ${money(inv.gst)} makes ${money(total)}.`);

  // 6. Has this invoice been seen before?
  const dup = ctx.invoices.find((o) => o.invoice_id !== inv.invoice_id && o.supplier_id === inv.supplier_id && o.status !== 'rejected' && earlier(o)
    && ((norm(o.supplier_ref) && norm(o.supplier_ref) === norm(inv.supplier_ref)) || (round2(o.total) === round2(total) && o.invoice_date === inv.invoice_date)));
  if (dup) add('duplicate', 'Not a duplicate', false, `Supplier invoice number ${inv.supplier_ref} was already received as ${dup.invoice_id} (${(INVOICE_STATUS[dup.status] || ['', dup.status])[1].toLowerCase()}, dated ${fmtDate(dup.invoice_date)}, ${money(dup.total)}).`,
    { short: 'Looks like a duplicate', risk: total, ask: `Invoice ${inv.supplier_ref} looks like one we have already received (${money(dup.total)}, dated ${fmtDate(dup.invoice_date)}). Please confirm it is not a duplicate.` });
  else add('duplicate', 'Not a duplicate', true, 'Not seen before from this supplier.');

  // 7. Bank account against the supplier record. Payments always go to the account on file.
  const invBank = digitsOf(inv.bank_account);
  const fileBank = digitsOf(sup && sup.bank_account);
  if (invBank && fileBank && invBank !== fileBank) {
    add('bank', 'Bank account matches the one on file', false, `The invoice shows ${inv.bank_account}, but the account on file is ${sup.bank_account}. Phone the supplier on a number you already have before paying anything. Payments always go to the account on file.`,
      { short: 'Bank account is not the one on file', level: 'high', risk: total, ask: `The bank account on this invoice (${inv.bank_account}) is different from the one we hold on file. Please phone us to confirm any change of bank details. We will not pay to a different account until we have spoken.` });
  } else {
    add('bank', 'Bank account matches the one on file', true, invBank ? 'Same account as on file.' : 'No account on the invoice; payment goes to the account on file.');
  }

  const failed = checks.filter((c) => !c.ok);
  const result = failed.length ? 'Review' : 'Clean';
  return {
    contract, checks, result,
    at_risk: failed.reduce((m, c) => Math.max(m, c.risk), 0),
    due_date: dueDateFor(inv.invoice_date, Number(cfg.pay_day || 20)),
    approver_role: failed.length || total > Number(cfg.manager_limit || 2500) ? 'owner' : 'manager',
    summary: failed.map((c) => c.text).join(' '),
  };
};

// "Check new invoices": reads every invoice that has not been checked, matches it to its contract and delivery docket,
// runs the checks, and asks the right person for a decision. It never approves or pays anything.
// Returns { updates, messages, audit, summary }.
const cfg = configFrom();
const base = cfg.base_url;
const ctx = {
  cfg,
  suppliers: Object.fromEntries(tableRows('Suppliers').map((s) => [s.supplier_id, s])),
  contracts: tableRows('Contracts'),
  dockets: tableRows('Dockets'),
  invoices: tableRows('Invoices'),
  used: {},
};
// How much of each contract is already used: approved, scheduled and paid invoices, plus clean ones waiting for approval.
for (const i of ctx.invoices) {
  if (i.contract_id && ['matched', 'approved', 'scheduled', 'paid'].includes(i.status)) ctx.used[i.contract_id] = (ctx.used[i.contract_id] || 0) + Number(i.qty);
}
const pending = ctx.invoices.filter((i) => i.status === 'received').sort((a, b) => String(a.received_at).localeCompare(String(b.received_at)) || a.invoice_id.localeCompare(b.invoice_id));
if (!pending.length) return [{ json: { updates: [], messages: [], audit: [], summary: 'No new invoices to check.' } }];

const now = nowIso();
const updates = [];
const audit = [];
const queue = { owner: [], manager: [] };
for (const inv of pending) {
  const r = checkInvoice(inv, ctx);
  if (r.contract && r.result === 'Clean') ctx.used[r.contract.contract_id] = (ctx.used[r.contract.contract_id] || 0) + Number(inv.qty);
  const approver = approverFor(r.approver_role, cfg);
  const supplier = ctx.suppliers[inv.supplier_id];
  const reviewToken = newToken();
  updates.push({
    id: inv.id, status: r.result === 'Clean' ? 'matched' : 'flagged', contract_id: r.contract ? r.contract.contract_id : '', result: r.result,
    reasons: JSON.stringify(r.checks), at_risk: r.at_risk, checked_at: now, due_date: r.due_date, approver_role: r.approver_role,
    approver_name: approver.name, review_token: reviewToken, approval_requested_at: now,
  });
  queue[r.approver_role].push({ inv, r, supplier, link: `${base}/webhook/invoices/review?t=${reviewToken}` });
  audit.push(auditRow('Agent', 'agent', 'Invoices', inv.invoice_id,
    r.result === 'Clean' ? 'Matched to contract' : 'Flagged for review',
    r.result === 'Clean' ? `${supplier.name} ${inv.supplier_ref}, ${money(inv.total)}. ${r.contract.contract_id}: all 7 checks passed. Needs ${approver.name}.` : `${supplier.name} ${inv.supplier_ref}, ${money(inv.total)}. ${r.summary}`));
}

// One digest per approver, not one message per invoice.
const messages = [];
for (const role of ['owner', 'manager']) {
  const items = queue[role];
  if (!items.length) continue;
  const who = approverFor(role, cfg);
  const flagged = items.filter((x) => x.r.result === 'Review');
  const clean = items.filter((x) => x.r.result === 'Clean');
  const total = round2(items.reduce((s, x) => s + Number(x.inv.total), 0));
  const line = (x) => `- ${x.supplier.name} ${x.inv.supplier_ref}, ${x.inv.description}: ${money(x.inv.total)}${x.r.result === 'Review' ? `. FLAGGED: ${x.r.checks.find((c) => !c.ok).text}` : ''}\n  ${x.link}`;
  const queueLink = `${base}/webhook/invoices/queue?t=${who.token}`;
  messages.push(msg({
    channel: 'Email', to_name: who.name, to_address: who.email, link: queueLink, related: `${items.length} invoices`, workflow: 'Invoice approval request',
    subject: `${items.length} invoice${items.length === 1 ? '' : 's'} waiting for your yes (${money(total)})${flagged.length ? `, ${flagged.length} flagged` : ''}`,
    body: [`Kia ora ${firstName(who.name)},`, '',
      `${items.length} supplier invoice${items.length === 1 ? ' is' : 's are'} waiting for your decision, ${money(total)} in all. The farm admin agent has checked each one against its contract and delivery docket.`,
      flagged.length ? `\nFlagged, so please look closely:\n${flagged.map(line).join('\n')}` : '',
      clean.length ? `\nAll checks passed:\n${clean.map(line).join('\n')}` : '',
      '', 'Nothing is approved or paid until you decide. This message is automated.'].filter((x) => x !== '').join('\n'),
  }));
  messages.push(...reach({ name: who.name, phone: who.phone }, {
    sms: `Kia ora ${firstName(who.name)}, ${items.length} invoice${items.length === 1 ? '' : 's'} (${money(total)}) need your yes${flagged.length ? `, ${flagged.length} flagged` : ''}. Nothing is paid until you decide:`,
    link: queueLink, related: `${items.length} invoices`, workflow: 'Invoice approval request',
  }, 'sms'));
  audit.push(auditRow('Agent', 'agent', 'Invoices', `${items.length} invoices`, `Asked ${who.name} (${who.title}) to decide`, `${flagged.length} flagged, ${clean.length} clean, ${money(total)}. Sent by email and SMS.`));
}

const flaggedTotal = updates.filter((u) => u.result === 'Review').length;
return [{ json: { updates, messages, audit, summary: `Checked ${pending.length} invoices: ${pending.length - flaggedTotal} clean, ${flaggedTotal} flagged for review. Nothing is approved or paid until a person decides.` } }];

// Shared helpers injected at the top of every Code node by scripts/build-workflows.mjs.
const TZ = 'Pacific/Auckland';
const DAY_MS = 86400000;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const round2 = (n) => Math.round(Number((Number(n || 0) * 100).toFixed(6))) / 100;
const money = (n) => new Intl.NumberFormat('en-NZ', { style: 'currency', currency: 'NZD' }).format(Number(n || 0));
const priceText = (n) => '$' + Number(n || 0).toLocaleString('en-NZ', { minimumFractionDigits: 2, maximumFractionDigits: 4 });
const qtyText = (n) => Number(n || 0).toLocaleString('en-NZ', { maximumFractionDigits: 2 });
const unitText = (qty, unit) => (Number(qty) !== 1 && { load: 'loads', bale: 'bales' }[unit]) || unit;
const newToken = () => require('crypto').randomBytes(18).toString('hex');
// Each call is one millisecond later than the last, so rows written in one run keep their order.
let _seq = 0;
const nowIso = () => new Date(Date.now() + _seq++).toISOString();

// Calendar dates are plain "YYYY-MM-DD" strings in New Zealand time, so this PC's own clock never matters.
const nzToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const dateOf = (s) => new Date(`${String(s).slice(0, 10)}T00:00:00Z`);
const isoDay = (d) => d.toISOString().slice(0, 10);
const addDays = (s, n) => isoDay(new Date(dateOf(s).getTime() + n * DAY_MS));
const addMonths = (s, n) => {
  const d = dateOf(s);
  const day = d.getUTCDate();
  const target = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + n, 1));
  const last = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0)).getUTCDate();
  target.setUTCDate(Math.min(day, last));
  return isoDay(target);
};
const daysBetween = (from, to) => Math.round((dateOf(to) - dateOf(from)) / DAY_MS);
const fmtDate = (s) => (s ? dateOf(s).toLocaleDateString('en-NZ', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' }) : '—');
const fmtLong = (s) => (s ? dateOf(s).toLocaleDateString('en-NZ', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : '—');
const fmtTime = (iso) => (iso ? new Date(iso).toLocaleString('en-NZ', { timeZone: TZ, day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit', hour12: true }) : '');
const ago = (iso) => {
  if (!iso) return '';
  const s = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
  if (s < 60) return 'just now';
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  return `${Math.round(s / 86400)} d ago`;
};

// Every Code node runs right after "Load data", whose single item holds one array per data table.
const DATA = $input.first().json || {};
const tableRows = (table) => (Array.isArray(DATA[table]) ? DATA[table] : []);
const configFrom = () => Object.fromEntries(tableRows('Config').map((r) => [r.key, r.value]));
const firstName = (name) => String(name || '').split(' ')[0];
const person = (cfg, role) => ({ name: cfg[`${role}_name`] || '', email: cfg[`${role}_email`] || '', phone: cfg[`${role}_phone`] || '' });

// A message for the Shared · Send message workflow. Nothing is sent from anywhere else.
const msg = (m) => ({
  channel: m.channel, to_name: m.to_name || '', to_address: m.to_address || '', subject: m.subject || '',
  body: m.body || '', link: m.link || '', related: m.related || '', workflow: m.workflow || '',
});
// Text the phone if we have one, otherwise email. `both` sends the email as well.
const reach = (p, m, how = 'auto') => {
  const out = [];
  const to = { to_name: p.name, related: m.related, workflow: m.workflow };
  if (p.phone && how !== 'email') out.push(msg({ ...to, channel: 'SMS', to_address: p.phone, body: m.sms || m.body, link: m.link }));
  if (p.email && (how === 'email' || how === 'both' || !p.phone)) out.push(msg({ ...to, channel: 'Email', to_address: p.email, subject: m.subject, body: m.body, link: m.link }));
  return out;
};
// One line of the audit trail: who did what, to what, and when.
const auditRow = (actor, type, flow, subject, action, detail = '') => ({
  at: nowIso(), actor, actor_type: type, flow, subject: String(subject).slice(0, 200), action: String(action).slice(0, 200), detail: String(detail).slice(0, 700),
});
// The page a webhook link returns after a person acts: back to the console, on the same tab, with a notice.
const backToConsole = (cfg, tab, notice) => `${cfg.base_url}/webhook/console?tab=${encodeURIComponent(tab || 'gate')}&done=${encodeURIComponent(notice)}`;

const pill = (tone, text) => `<span class="pill ${tone}">${esc(text)}</span>`;
const callout = (tone, html) => `<div class="callout ${tone}">${html}</div>`;

