// POST /webhook/invoices/review: a person approves, approves anyway (with a reason), queries the supplier or rejects.
// The agent never decides. Returns { updates, messages, audit, html }.
const cfg = configFrom();
const body = $('Approver decides').first().json.body || {};
const token = String(body.t || '');
const decision = String(body.decision || '');
const note = String(body.note || '').trim().slice(0, 500);
const inv = tableRows('Invoices').find((i) => token && i.review_token === token);
const none = { updates: [], messages: [], audit: [] };
if (!inv) return [{ json: { ...none, html: page('Link not found', `<h1>This link is no longer valid</h1><p class="muted">Ask ${esc(cfg.admin_name)} for a new one.</p>`) } }];

const sup = supplierOf(inv);
const approver = approverFor(inv.approver_role, cfg);
const back = `<p><a class="btn line" href="${cfg.base_url}/webhook/invoices/queue?t=${esc(approver.token)}">Back to your list</a></p>`;
if (!['matched', 'flagged'].includes(inv.status)) {
  return [{ json: { ...none, html: page('Already decided', `<h1>Already decided</h1>${callout('info', `This invoice is <b>${esc((INVOICE_STATUS[inv.status] || ['', inv.status])[1].toLowerCase())}</b>. Nothing more to do.`)}${back}`) } }];
}
const again = (error, extra = {}) => [{ json: { ...none, html: page(`Invoice ${inv.supplier_ref}`, reviewBody(inv, cfg, { error, ...extra })) } }];
const failed = failedChecks(inv);
const now = nowIso();
const decided = { decided_at: now, decided_by: approver.name, decision_note: note };

if (decision === 'approve') {
  if (failed.length) return again('This invoice is flagged. Ask the supplier, reject it, or approve it anyway and say why.');
  return [{ json: { ...none,
    updates: [{ id: inv.id, status: 'approved', decision: 'approved', ...decided }],
    audit: [auditRow(approver.name, 'person', 'Invoices', inv.invoice_id, 'Approved', `${sup.name} ${inv.supplier_ref}, ${money(inv.total)}. Due ${fmtDate(inv.due_date)}.`)],
    html: page('Approved', `<h1>Approved</h1>${callout('ok', `<b>${money(inv.total)} to ${esc(sup.name)} is approved.</b> It goes into the payment file for ${fmtDate(inv.due_date)}. The agent has not paid anything: you upload the payment file to your bank yourself.`)}${back}`),
  } }];
}
if (decision === 'approve_anyway') {
  if (!failed.length) return again('Nothing was flagged on this invoice, so there is nothing to approve anyway. Use Approve.');
  if (note.length < 8) return again('Say why it is safe to pay, in a sentence. Your reason goes into the record.', { note });
  return [{ json: { ...none,
    updates: [{ id: inv.id, status: 'approved', decision: 'approved anyway', ...decided }],
    audit: [auditRow(approver.name, 'person', 'Invoices', inv.invoice_id, 'Approved anyway', `Overrode: ${failed.map((c) => c.label.toLowerCase()).join(', ')}. Reason: ${note}`)],
    html: page('Approved', `<h1>Approved anyway</h1>${callout('warn', `<b>${money(inv.total)} to ${esc(sup.name)} is approved.</b> Your reason is in the record. Payment goes to the bank account on file${failed.some((c) => c.id === 'bank') ? ', not the account on the invoice' : ''}.`)}${back}`),
  } }];
}
if (decision === 'query') {
  const text = String(body.query_text || '').trim().slice(0, 2500);
  if (text.length < 30) return again('Write the message to the supplier, or keep the draft.', { query_text: text });
  return [{ json: { ...none,
    updates: [{ id: inv.id, status: 'queried', decision: 'queried', ...decided, decision_note: 'Question sent to the supplier.' }],
    messages: [msg({ channel: 'Email', to_name: sup.contact_name, to_address: sup.contact_email, subject: `Question about invoice ${inv.supplier_ref}`, body: `${text}\n\nSent for ${approver.name} at ${cfg.business_name}.`, related: inv.invoice_id, workflow: 'Invoice query' })],
    audit: [
      auditRow(approver.name, 'person', 'Invoices', inv.invoice_id, 'Approved the question to the supplier', `${failed.length} flag${failed.length === 1 ? '' : 's'} on ${sup.name} ${inv.supplier_ref}.`),
      auditRow('Agent', 'agent', 'Invoices', inv.invoice_id, 'Sent the question to the supplier', `Emailed ${sup.contact_name} at ${sup.name}, after ${approver.name} approved the wording.`),
    ],
    html: page('Question sent', `<h1>Question sent</h1>${callout('ok', `<b>${esc(sup.contact_name)} at ${esc(sup.name)} has your question.</b> The invoice is on hold. When a corrected invoice arrives, add it and the agent checks it again.`)}${back}`),
  } }];
}
if (decision === 'reject') {
  return [{ json: { ...none,
    updates: [{ id: inv.id, status: 'rejected', decision: 'rejected', ...decided }],
    audit: [auditRow(approver.name, 'person', 'Invoices', inv.invoice_id, 'Rejected', `${sup.name} ${inv.supplier_ref}, ${money(inv.total)}.${note ? ` Reason: ${note}` : ''}`)],
    html: page('Rejected', `<h1>Rejected</h1>${callout('info', `<b>Invoice ${esc(inv.supplier_ref)} is rejected.</b> It will not be paid.`)}${back}`),
  } }];
}
return again('Choose one of the options below.');

// Shared helpers injected at the top of every Code node by scripts/build-workflows.mjs.
const TZ = 'Pacific/Auckland';
const DAY_MS = 86400000;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const round2 = (n) => Math.round(Number((Number(n || 0) * 100).toFixed(6))) / 100;
const money = (n) => new Intl.NumberFormat('en-NZ', { style: 'currency', currency: 'NZD' }).format(Number(n || 0));
const priceText = (n) => '$' + Number(n || 0).toLocaleString('en-NZ', { minimumFractionDigits: 2, maximumFractionDigits: 4 });
const qtyText = (n) => Number(n || 0).toLocaleString('en-NZ', { maximumFractionDigits: 2 });
const unitText = (qty, unit) => (Number(qty) !== 1 && { load: 'loads', bale: 'bales' }[unit]) || unit;
const newToken = () => require('crypto').randomBytes(18).toString('hex');
// Each call is one millisecond later than the last, so rows written in one run keep their order.
let _seq = 0;
const nowIso = () => new Date(Date.now() + _seq++).toISOString();

// Calendar dates are plain "YYYY-MM-DD" strings in New Zealand time, so this PC's own clock never matters.
const nzToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const dateOf = (s) => new Date(`${String(s).slice(0, 10)}T00:00:00Z`);
const isoDay = (d) => d.toISOString().slice(0, 10);
const addDays = (s, n) => isoDay(new Date(dateOf(s).getTime() + n * DAY_MS));
const addMonths = (s, n) => {
  const d = dateOf(s);
  const day = d.getUTCDate();
  const target = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + n, 1));
  const last = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0)).getUTCDate();
  target.setUTCDate(Math.min(day, last));
  return isoDay(target);
};
const daysBetween = (from, to) => Math.round((dateOf(to) - dateOf(from)) / DAY_MS);
const fmtDate = (s) => (s ? dateOf(s).toLocaleDateString('en-NZ', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' }) : '—');
const fmtLong = (s) => (s ? dateOf(s).toLocaleDateString('en-NZ', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : '—');
const fmtTime = (iso) => (iso ? new Date(iso).toLocaleString('en-NZ', { timeZone: TZ, day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit', hour12: true }) : '');
const ago = (iso) => {
  if (!iso) return '';
  const s = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
  if (s < 60) return 'just now';
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  return `${Math.round(s / 86400)} d ago`;
};

// Every Code node runs right after "Load data", whose single item holds one array per data table.
const DATA = $input.first().json || {};
const tableRows = (table) => (Array.isArray(DATA[table]) ? DATA[table] : []);
const configFrom = () => Object.fromEntries(tableRows('Config').map((r) => [r.key, r.value]));
const firstName = (name) => String(name || '').split(' ')[0];
const person = (cfg, role) => ({ name: cfg[`${role}_name`] || '', email: cfg[`${role}_email`] || '', phone: cfg[`${role}_phone`] || '' });

// A message for the Shared · Send message workflow. Nothing is sent from anywhere else.
const msg = (m) => ({
  channel: m.channel, to_name: m.to_name || '', to_address: m.to_address || '', subject: m.subject || '',
  body: m.body || '', link: m.link || '', related: m.related || '', workflow: m.workflow || '',
});
// Text the phone if we have one, otherwise email. `both` sends the email as well.
const reach = (p, m, how = 'auto') => {
  const out = [];
  const to = { to_name: p.name, related: m.related, workflow: m.workflow };
  if (p.phone && how !== 'email') out.push(msg({ ...to, channel: 'SMS', to_address: p.phone, body: m.sms || m.body, link: m.link }));
  if (p.email && (how === 'email' || how === 'both' || !p.phone)) out.push(msg({ ...to, channel: 'Email', to_address: p.email, subject: m.subject, body: m.body, link: m.link }));
  return out;
};
// One line of the audit trail: who did what, to what, and when.
const auditRow = (actor, type, flow, subject, action, detail = '') => ({
  at: nowIso(), actor, actor_type: type, flow, subject: String(subject).slice(0, 200), action: String(action).slice(0, 200), detail: String(detail).slice(0, 700),
});
// The page a webhook link returns after a person acts: back to the console, on the same tab, with a notice.
const backToConsole = (cfg, tab, notice) => `${cfg.base_url}/webhook/console?tab=${encodeURIComponent(tab || 'gate')}&done=${encodeURIComponent(notice)}`;

const pill = (tone, text) => `<span class="pill ${tone}">${esc(text)}</span>`;
const callout = (tone, html) => `<div class="callout ${tone}">${html}</div>`;

// One type family (Figtree, from Google Fonts) with the system font as the fallback when offline.
const FONT_LINK = '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Figtree:wght@400..800&display=swap">';
// The business's mark: three tussock blades on dark teal.
const BRAND_MARK = '<svg class="mark" width="34" height="34" viewBox="0 0 34 34" aria-hidden="true"><rect width="34" height="34" rx="10" fill="#0e3a35"/><g fill="none" stroke="#d6f04a" stroke-width="2.4" stroke-linecap="round"><path d="M17 26V10"/><path d="M17 26c-.8-5.6-3.8-9-8.5-11"/><path d="M17 26c.8-5.6 3.8-9 8.5-11"/></g></svg>';

